    prof.bezierCurveTo(-0.5, 5.6, 0, 4.6, 0.4, 3.4); prof.bezierCurveTo(3, 2.4, 6, 1.2, 9, 0); prof.lineTo(-27, 0);
    const cover = new T.ExtrudeGeometry(prof, { depth: 5.2, bevelEnabled: true, bevelThickness: 1.1, bevelSize: 0.9, bevelSegments: 4, curveSegments: 14 });
    cover.translate(0, 6.8, -2.6);
