    x.fillStyle = car.col; x.fillRect(0, 0, 512, 192);
    x.fillStyle = car.col2;
    [-1, 1].forEach((s) => { x.beginPath(); x.moveTo(X(-22), Y(2 * s)); x.lineTo(X(4), Y(10.5 * s)); x.lineTo(X(8), Y(10.5 * s)); x.lineTo(X(-18), Y(1 * s)); x.closePath(); x.fill(); });
    x.fillRect(X(26), 0, X(33) - X(26), 192);
    x.fillRect(X(-24), Y(0.9), X(-6) - X(-24), Y(-0.9) - Y(0.9));
    x.fillStyle = 'rgba(255,255,255,0.92)';
    x.fillRect(X(-8), Y(10), X(-1) - X(-8), Y(8.2) - Y(10)); x.fillRect(X(-8), Y(-8.2), X(-1) - X(-8), Y(-10) - Y(-8.2));
    x.save(); x.translate(X(19), Y(0)); x.rotate(Math.PI / 2); x.fillStyle = '#ffffff'; x.font = 'bold 30px sans-serif'; x.textAlign = 'center'; x.textBaseline = 'middle'; x.fillText(String(car.num), 0, 0); x.restore();
