    const paint = new T.MeshPhysicalMaterial(Object.assign({ map: this.liveryTex(car) }, paintOpts));
    const col = new T.MeshPhysicalMaterial(Object.assign({ color: new T.Color(car.col) }, paintOpts));
    const col2 = new T.MeshPhysicalMaterial(Object.assign({ color: new T.Color(car.col2) }, paintOpts));
    const helmetM = new T.MeshPhysicalMaterial({ color: new T.Color(car.isPlayer ? '#ffd400' : car.col2), roughness: 0.25, clearcoat: 1 });
