    add(G.box, col, 28.2, 2.9, 0, 2.6, 0.6, 30);
    add(G.box, col2, 29.6, 3.9, 0, 1.8, 0.5, 29);
    add(G.box, col, -30.6, 13.6, 0, 4.6, 0.9, 22.4);
    add(G.box, col2, -27.6, 15.3, 0, 2.9, 0.7, 22.4);
    add(G.box, M.carbon, -31, 9, 0, 1, 8, 0.8);
    add(G.box, M.carbon, -30.6, 6.2, 0, 3, 0.6, 20);
