      this.txt(this.def.full + '  ·  ' + this.def.country, W / 2, H - 132, 18, 600, '#d0d4da', 'center');
      this.txt(this.session === 'tt' ? 'Hot laps on an empty track. Beat your record.' : quali ? 'One flying lap. The fastest time takes pole position.' : this.cfg.laps + ' laps  ·  You start P' + me.grid + ' of ' + this.cars.length, W / 2, H - 100, 16, 400, '#b4b9c2', 'center');
